244	    /**
245	     * Loads the owner with the given id and, when it exists, produces the response through
246	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
247	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
248	     * the not-found response are written in exactly one place rather than copied into each method.
249	     *
250	     * @param ownerId the id of the owner to load
251	     * @param action builds the response for an existing owner
252	     * @param <T> the response body type
253	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
254	     */
255	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
256	        Owner owner = this.clinicService.findOwnerById(ownerId);
257	        if (owner == null) {
258	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
259	        }
260	        return action.apply(owner);
261	    }
